--
-- Name: next_invoice_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_invoice_number() RETURNS TABLE(out_fiscal_year character, out_sequence_no integer, out_formatted_number character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_fy char(7) := compute_fiscal_year();
  v_fy_compact char(4);
  v_seq bigint;
BEGIN
    VALUES (v_fy, 1)
    ON CONFLICT (fiscal_year)
    DO UPDATE SET current_value = invoice_sequences.current_value + 1, updated_at = now()
  RETURNING current_value INTO v_seq;

  IF v_seq > 9999999 THEN
    RAISE EXCEPTION 'Invoice sequence exhausted for FY %; need multi-series prefix (e.g. INV2/...).', v_fy;
  END IF;

  v_fy_compact := substring(v_fy, 3, 2) || substring(v_fy, 6, 2);

  RETURN QUERY SELECT
    v_fy,
    v_seq::integer,
    ('INV/' || v_fy_compact || '/' || lpad(v_seq::text, 7, '0'))::varchar(16);
END $$;


--
-- Name: purge_expired_idempotency_keys(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_idempotency_keys(grace interval DEFAULT '7 days'::interval) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM mobile_idempotency_keys WHERE expires_at < now() - grace;
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: FUNCTION purge_expired_idempotency_keys(grace interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_expired_idempotency_keys(grace interval) IS 'F11.7.2: deletes mobile_idempotency_keys rows whose expires_at is older than now()-grace. Default 7d grace beyond expiry. Schedule daily.';


--
-- Name: purge_stale_audit_logs(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_stale_audit_logs(retention interval DEFAULT '3 years'::interval) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE deleted_count integer;
BEGIN
    DELETE FROM audit_logs WHERE created_at < now() - retention;
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END $$;


--
-- Name: purge_stale_auto_saves(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_stale_auto_saves(retention interval DEFAULT '7 days'::interval) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM auto_saves WHERE updated_at < now() - retention;
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: FUNCTION purge_stale_auto_saves(retention interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_stale_auto_saves(retention interval) IS 'F7.9.3: Deletes auto_saves rows older than `retention` (default 7 days). Schedule via pg_cron or external cron daily. Returns count of deleted rows.';


--
-- Name: purge_stale_notifications(interval, interval, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_stale_notifications(delivered_read_retention interval DEFAULT '90 days'::interval, unresolved_retention interval DEFAULT '365 days'::interval, soft_deleted_retention interval DEFAULT '30 days'::interval) RETURNS TABLE(deleted_delivered integer, deleted_unresolved integer, deleted_soft_purged integer, deleted_delivery_log integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  d1 integer; d2 integer; d3 integer;
  d_log_t1 integer; d_log_t2 integer; d_log_t3 integer;
  ids_t1 uuid[]; ids_t2 uuid[]; ids_t3 uuid[];
BEGIN
  -- Tier 1: DELIVERED + is_read=true older than 90 days
  SELECT ARRAY(
    SELECT id FROM notifications
    WHERE delivery_status = 'DELIVERED' AND is_read = true
      AND created_at < now() - delivered_read_retention
  ) INTO ids_t1;

  DELETE FROM notification_delivery_log WHERE notification_id = ANY(ids_t1);
  GET DIAGNOSTICS d_log_t1 = ROW_COUNT;
  DELETE FROM notifications WHERE id = ANY(ids_t1);
  GET DIAGNOSTICS d1 = ROW_COUNT;

  -- Tier 2: FAILED/PENDING older than 365 days
  SELECT ARRAY(
    SELECT id FROM notifications
    WHERE delivery_status IN ('FAILED','PENDING')
      AND created_at < now() - unresolved_retention
  ) INTO ids_t2;

  DELETE FROM notification_delivery_log WHERE notification_id = ANY(ids_t2);
  GET DIAGNOSTICS d_log_t2 = ROW_COUNT;
  DELETE FROM notifications WHERE id = ANY(ids_t2);
  GET DIAGNOSTICS d2 = ROW_COUNT;

  -- Tier 3 (NEW 2026-05-08): soft-deleted (is_deleted=true) older than 30 days
  -- Source: user "Clear All" / per-row "Delete" actions or admin clear.
  SELECT ARRAY(
    SELECT id FROM notifications
    WHERE is_deleted = true
      AND deleted_at IS NOT NULL
      AND deleted_at < now() - soft_deleted_retention
  ) INTO ids_t3;

  DELETE FROM notification_delivery_log WHERE notification_id = ANY(ids_t3);
  GET DIAGNOSTICS d_log_t3 = ROW_COUNT;
  DELETE FROM notifications WHERE id = ANY(ids_t3);
  GET DIAGNOSTICS d3 = ROW_COUNT;

  RETURN QUERY SELECT d1, d2, d3, d_log_t1 + d_log_t2 + d_log_t3;
END;
$$;


--
-- Name: purge_stale_performance_metrics(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_stale_performance_metrics(retention interval DEFAULT '7 days'::interval) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE deleted_count integer;
BEGIN
    DELETE FROM performance_metrics WHERE "timestamp" < now() - retention;
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END $$;


