--
-- Name: attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attachments (
    filename character varying(255) NOT NULL,
    original_name character varying(255) NOT NULL,
    file_path character varying(500) NOT NULL,
    file_size bigint NOT NULL,
    mime_type character varying(100) NOT NULL,
    uploaded_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    id bigint NOT NULL,
    case_id uuid NOT NULL,
    verification_task_id uuid,
    preview_rendition_path character varying(500),
    preview_rendition_kind character varying(20),
    rendition_status character varying(20),
    rendition_error text,
    rendition_generated_at timestamp with time zone,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    deletion_reason text,
    sha256_hash text,
    storage_key text
);


--
-- Name: COLUMN attachments.file_size; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.file_size IS 'F8.1.2: bigint to support files > 2GB.';


--
-- Name: COLUMN attachments.preview_rendition_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.preview_rendition_path IS 'Optional rendition for in-app preview. PDF for office docs, JPEG for TIFF/HEIC. NULL when original is directly previewable (jpg, png, pdf, etc.) or rendition pending/failed.';


--
-- Name: COLUMN attachments.preview_rendition_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.preview_rendition_kind IS 'Kind of rendition: pdf | jpeg. NULL when no rendition needed/present.';


--
-- Name: COLUMN attachments.rendition_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.rendition_status IS 'pending | success | failed | not_required';


--
-- Name: COLUMN attachments.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.deleted_at IS 'F8.1.1: soft-delete timestamp (mirror of verification_attachments). NULL = active.';


--
-- Name: COLUMN attachments.sha256_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.sha256_hash IS 'F8.1.3: 64-char hex SHA-256 of file content. NULL = legacy / not yet computed.';


--
-- Name: COLUMN attachments.storage_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.storage_key IS 'Object-storage key. Replaces file_path after cutover.';


