--
-- Name: case_deduplication_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.case_deduplication_audit (
    search_criteria jsonb NOT NULL,
    duplicates_found jsonb,
    user_decision character varying(20) NOT NULL,
    rationale text,
    performed_by uuid NOT NULL,
    performed_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    id bigint NOT NULL,
    case_id uuid NOT NULL,
    CONSTRAINT chk_dedup_audit_decision CHECK (((user_decision)::text = ANY (ARRAY[('CREATE_NEW'::character varying)::text, ('USE_EXISTING'::character varying)::text, ('MERGE_CASES'::character varying)::text, ('NO_DUPLICATES'::character varying)::text, ('NO_DUPLICATES_FOUND'::character varying)::text])))
);


--
-- Name: TABLE case_deduplication_audit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.case_deduplication_audit IS 'Audit trail for case deduplication decisions and duplicate detection results';


--
-- Name: COLUMN case_deduplication_audit.search_criteria; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.case_deduplication_audit.search_criteria IS 'JSON object containing the search criteria used for duplicate detection';


--
-- Name: COLUMN case_deduplication_audit.duplicates_found; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.case_deduplication_audit.duplicates_found IS 'JSON array of duplicate cases found during the search';


--
-- Name: COLUMN case_deduplication_audit.user_decision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.case_deduplication_audit.user_decision IS 'Decision made by the user: CREATE_NEW, USE_EXISTING, or MERGE_CASES';


--
-- Name: COLUMN case_deduplication_audit.rationale; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.case_deduplication_audit.rationale IS 'User-provided rationale for their deduplication decision';


--
-- Name: COLUMN case_deduplication_audit.performed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.case_deduplication_audit.performed_by IS 'User who performed the deduplication check and made the decision';


