CREATE TABLE public.clients (
    name character varying(100) NOT NULL,
    code character varying(20) NOT NULL,
    email character varying(100),
    phone character varying(20),
    address text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    id integer NOT NULL,
    logo_url character varying(500),
    stamp_url character varying(500),
    primary_color character varying(20),
    header_color character varying(20),
    deleted_at timestamp with time zone,
    gstin character(15),
    pan character(10),
    gstin_state_code character(2),
    billing_address_line1 character varying(255),
    billing_address_line2 character varying(255),
    billing_city_id integer,
    billing_state_id integer,
    billing_pincode character varying(10),
    tier character varying(20),
    billing_country_id integer,
    CONSTRAINT chk_clients_tier CHECK (((tier IS NULL) OR ((tier)::text = ANY (ARRAY[('STARTER'::character varying)::text, ('GROWTH'::character varying)::text, ('ENTERPRISE'::character varying)::text])))),
    CONSTRAINT clients_billing_pincode_format CHECK (((billing_pincode IS NULL) OR ((billing_pincode)::text ~ '^[1-9][0-9]{5}$'::text))),
    CONSTRAINT clients_gstin_format CHECK (((gstin IS NULL) OR (gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9][A-Z][0-9A-Z]$'::text))),
    CONSTRAINT clients_gstin_state_code_format CHECK (((gstin_state_code IS NULL) OR (gstin_state_code ~ '^[0-9]{2}$'::text))),
    CONSTRAINT clients_gstin_state_code_match CHECK (((gstin IS NULL) OR (gstin_state_code IS NULL) OR (SUBSTRING(gstin FROM 1 FOR 2) = (gstin_state_code)::text))),
    CONSTRAINT clients_pan_format CHECK (((pan IS NULL) OR (pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$'::text)))
);


