--
-- Name: invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoices (
    id bigint NOT NULL,
    invoice_number character varying(100) NOT NULL,
    client_id integer NOT NULL,
    product_id integer NOT NULL,
    client_name character varying(200) NOT NULL,
    amount numeric(12,2) DEFAULT 0 NOT NULL,
    subtotal_amount numeric(12,2) DEFAULT 0 NOT NULL,
    tax_amount numeric(12,2) DEFAULT 0 NOT NULL,
    total_amount numeric(12,2) DEFAULT 0 NOT NULL,
    currency character varying(10) DEFAULT 'INR'::character varying NOT NULL,
    status character varying(50) DEFAULT 'DRAFT'::character varying NOT NULL,
    billing_period_from timestamp with time zone,
    billing_period_to timestamp with time zone,
    issue_date timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    due_date timestamp with time zone NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    sent_at timestamp with time zone,
    paid_date timestamp with time zone,
    payment_method character varying(50),
    transaction_id character varying(100),
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    cgst_rate numeric(5,2),
    cgst_amount numeric(12,2),
    sgst_rate numeric(5,2),
    sgst_amount numeric(12,2),
    igst_rate numeric(5,2),
    igst_amount numeric(12,2),
    place_of_supply character(2),
    supply_type character varying(20),
    is_locked boolean DEFAULT false NOT NULL,
    fiscal_year character(7) NOT NULL,
    invoice_sequence_no integer NOT NULL,
    CONSTRAINT chk_invoices_amount_arithmetic CHECK ((total_amount = (subtotal_amount + tax_amount))),
    CONSTRAINT chk_invoices_fiscal_year_format CHECK ((fiscal_year ~ '^[0-9]{4}-[0-9]{2}$'::text)),
    CONSTRAINT chk_invoices_gst_consistency CHECK (((supply_type IS NULL) OR (((supply_type)::text = 'INTRA_STATE'::text) AND (cgst_amount IS NOT NULL) AND (sgst_amount IS NOT NULL) AND (igst_amount IS NULL)) OR (((supply_type)::text = 'INTER_STATE'::text) AND (igst_amount IS NOT NULL) AND (cgst_amount IS NULL) AND (sgst_amount IS NULL)) OR (((supply_type)::text = 'EXPORT'::text) AND (cgst_amount IS NULL) AND (sgst_amount IS NULL) AND (igst_amount IS NULL)))),
    CONSTRAINT chk_invoices_supply_type CHECK (((supply_type IS NULL) OR ((supply_type)::text = ANY (ARRAY[('INTRA_STATE'::character varying)::text, ('INTER_STATE'::character varying)::text, ('EXPORT'::character varying)::text]))))
);


--
-- Name: COLUMN invoices.amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.amount IS 'F9.2.4 LEGACY: original single amount column. Modern usage = total_amount. Authoritative arithmetic: subtotal_amount + tax_amount = total_amount.';


--
-- Name: COLUMN invoices.supply_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.supply_type IS 'F9.2.1: INTRA_STATE | INTER_STATE | EXPORT — drives CGST+SGST vs IGST split.';


