CREATE TABLE public.kyc_document_verifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    verification_task_id uuid NOT NULL,
    case_id uuid NOT NULL,
    document_number character varying(100),
    document_holder_name character varying(255),
    document_file_path character varying(500),
    document_file_name character varying(255),
    document_file_size bigint,
    document_mime_type character varying(100),
    verification_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    verified_by uuid,
    verified_at timestamp with time zone,
    remarks text,
    rejection_reason text,
    assigned_to uuid,
    assigned_by uuid,
    assigned_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    document_details jsonb DEFAULT '{}'::jsonb,
    description text,
    rate_amount numeric(10,2),
    deleted_at timestamp with time zone,
    deleted_by uuid,
    deletion_reason text,
    sha256_hash text,
    final_status character varying(20),
    document_type_id integer,
    document_storage_key text,
    CONSTRAINT chk_kyc_doc_final_status CHECK (((final_status IS NULL) OR ((final_status)::text = ANY (ARRAY[('Positive'::character varying)::text, ('Negative'::character varying)::text, ('Refer'::character varying)::text, ('Fraud'::character varying)::text])))),
    CONSTRAINT chk_kyc_doc_workflow_status CHECK (((verification_status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('ASSIGNED'::character varying)::text, ('IN_PROGRESS'::character varying)::text, ('COMPLETED'::character varying)::text, ('REVOKED'::character varying)::text])))
);


