--

COMMENT ON COLUMN public.kyc_document_verifications.final_status IS 'F8.2.1 (outcome): NULL until reviewer decides. Mirror of verification_reports.final_status enum (Positive/Negative/Refer/Fraud).';


--
-- Name: COLUMN kyc_document_verifications.document_type_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kyc_document_verifications.document_type_id IS 'F8.2.2: FK to document_types(id). New canonical column; replaces varchar `document_type` after backfill phase.';


