    CONSTRAINT latest_location_pkey PRIMARY KEY (user_id),
    CONSTRAINT latest_location_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE
);

CREATE INDEX idx_latest_location_geo ON public.latest_location USING btree (latitude, longitude);

CREATE INDEX idx_latest_location_recorded_at ON public.latest_location USING btree (recorded_at DESC);


