    device_label character varying(200)
);


--
-- Name: COLUMN refresh_tokens.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.refresh_tokens.device_id IS 'A-CRIT-1: opaque client-generated device identifier. Mobile=platform deviceId; web=stable random in HttpOnly cookie. Together with user_id forms the partial-unique active-session key for selective revocation.';


--
-- Name: COLUMN refresh_tokens.device_fingerprint_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.refresh_tokens.device_fingerprint_hash IS 'A-CRIT-1: sha256 hex of (user-agent + accept-language + screen + tz). Helps detect device drift / session theft when device_id matches but fingerprint changes.';


--
-- Name: COLUMN refresh_tokens.device_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.refresh_tokens.device_label IS 'A-CRIT-1: human-friendly device name shown in admin force-logout UI (e.g. "Pixel 7 Pro · Mumbai"). Derived from user_agent at issue time.';


