-- Name: verification_attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verification_attachments (
    id bigint NOT NULL,
    case_id uuid NOT NULL,
    verification_type character varying(50) NOT NULL,
    filename character varying(255) NOT NULL,
    original_name character varying(255) NOT NULL,
    mime_type character varying(100) NOT NULL,
    file_path character varying(500) NOT NULL,
    thumbnail_path character varying(500),
    uploaded_by uuid NOT NULL,
    geo_location jsonb,
    photo_type character varying(50) DEFAULT 'verification'::character varying,
    submission_id character varying(100),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    verification_task_id uuid,
    sha256_hash text,
    server_sha256_hash text,
    hash_verified boolean DEFAULT false,
    server_signature text,
    file_size_bytes bigint,
    capture_time timestamp with time zone,
    device_id text,
    app_version text,
    exif_json jsonb,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    deletion_reason text,
    operation_id text,
    reverse_geocoded_address text,
    storage_key text,
    CONSTRAINT chk_verification_attachments_geo_location_shape CHECK (((geo_location IS NULL) OR ((geo_location ? 'latitude'::text) AND (geo_location ? 'longitude'::text) AND (jsonb_typeof((geo_location -> 'latitude'::text)) = 'number'::text) AND (jsonb_typeof((geo_location -> 'longitude'::text)) = 'number'::text))))
);


