--
-- Name: verification_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verification_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    verification_type_id integer NOT NULL,
    case_id uuid NOT NULL,
    verification_task_id uuid NOT NULL,
    verified_by uuid NOT NULL,
    form_type character varying(50) NOT NULL,
    final_status character varying(50) NOT NULL,
    verification_outcome character varying(100) NOT NULL,
    verification_date date NOT NULL,
    customer_name character varying(255),
    customer_phone character varying(50),
    customer_email character varying(255),
    contact_person character varying(255),
    met_person_name character varying(255),
    met_person_type character varying(50),
    met_person_designation character varying(100),
    met_person_confirmation text,
    met_person_relation character varying(100),
    met_person_status character varying(50),
    staying_person_name character varying(255),
    locality character varying(255),
    address_locatable character varying(50),
    address_rating character varying(50),
    address_structure character varying(100),
    address_structure_color character varying(100),
    address_floor character varying(50),
    address_status character varying(50),
    address_exist_at character varying(255),
    address_traceable text,
    applicant_staying_floor character varying(50),
    applicant_staying_status character varying(100),
    staying_status character varying(100),
    staying_period character varying(100),
    shifted_period character varying(100),
    flat_no character varying(50),
    flat_status character varying(50),
    house_status character varying(100),
    premises_status character varying(100),
    building_status character varying(100),
    property_status character varying(100),
    property_area numeric,
    approx_area integer,
    ownership_type character varying(100),
    resi_cum_office_status text,
    residence_setup character varying(100),
    door_color character varying(100),
    door_name_plate_status character varying(100),
    name_on_door_plate character varying(255),
    society_name_plate character varying(255),
    society_name_plate_status character varying(100),
    name_on_society_board character varying(255),
    landmark1 character varying(255),
    landmark2 character varying(255),
    landmark3 text,
    landmark4 text,
    office_status character varying(100),
    office_existence character varying(100),
    office_exists_status text,
    office_area numeric,
    office_approx_area integer,
    office_type character varying(100),
    applicant_working_status character varying(100),
    applicant_working_premises character varying(100),
    applicant_designation character varying(100),
    working_status character varying(100),
    working_period character varying(100),
    current_company_name character varying(255),
    current_company_period character varying(100),
    company_name character varying(255),
    company_nature_of_business text,
    company_name_plate_status character varying(100),
    name_on_board character varying(255),
    business_period character varying(100),
    business_status character varying(100),
    business_existence character varying(100),
    business_exists_status text,
    business_setup character varying(100),
    business_type character varying(100),
    business_approx_area integer,
    business_operating_address text,
    establishment_period character varying(100),
    staff_seen integer,
    staff_strength integer,
    total_staff integer,
    sitting_location character varying(100),
    name_of_company_owners character varying(255),
    owner_name character varying(255),
    builder_owner_name character varying(255),
    builder_type character varying(100),
    construction_activity character varying(100),
    project_name character varying(255),
    project_started_date date,
    project_completion_date date,
    project_completion_percentage integer,
    total_flats integer,
    total_wing integer,
    total_family_members integer,
    total_earning_member integer,
    tpc_name1 character varying(255),
    tpc_name2 character varying(255),
    tpc_met_person1 character varying(255),
    tpc_met_person2 character varying(255),
    tpc_confirmation1 text,
    tpc_confirmation2 text,
    name_on_noc character varying(255),
    authorised_signature character varying(255),
    document_shown character varying(100),
    document_type text,
    dominated_area character varying(255),
    feedback_from_neighbour character varying(255),
    political_connection character varying(255),
    security_confirmation character varying(100),
    active_client text,
    activity_stop_reason text,
    old_office_shifted_period character varying(100),
    old_business_shifted_period character varying(100),
    call_remark text,
    call_confirmation text,
    remarks text,
    other_observation text,
    total_images integer DEFAULT 0,
    total_selfies integer DEFAULT 0,
    CONSTRAINT chk_verification_reports_approx_area CHECK (((approx_area IS NULL) OR ((approx_area >= 1) AND (approx_area <= 100000)))),
    CONSTRAINT chk_verification_reports_business_area CHECK (((business_approx_area IS NULL) OR ((business_approx_area >= 1) AND (business_approx_area <= 100000)))),
    CONSTRAINT chk_verification_reports_final_status CHECK (((final_status)::text = ANY (ARRAY[('Positive'::character varying)::text, ('Negative'::character varying)::text, ('Refer'::character varying)::text, ('Fraud'::character varying)::text]))),
    CONSTRAINT chk_verification_reports_office_area CHECK (((office_approx_area IS NULL) OR ((office_approx_area >= 1) AND (office_approx_area <= 100000)))),
    CONSTRAINT chk_verification_reports_project_completion CHECK (((project_completion_percentage IS NULL) OR ((project_completion_percentage >= 0) AND (project_completion_percentage <= 100)))),
    CONSTRAINT chk_verification_reports_property_area CHECK (((property_area IS NULL) OR ((property_area >= (1)::numeric) AND (property_area <= (100000)::numeric)))),
    CONSTRAINT chk_verification_reports_staff_seen CHECK (((staff_seen IS NULL) OR (staff_strength IS NULL) OR ((staff_seen >= 0) AND (staff_seen <= staff_strength)))),
    CONSTRAINT chk_verification_reports_staff_strength CHECK (((staff_strength IS NULL) OR ((staff_strength >= 1) AND (staff_strength <= 10000)))),
    CONSTRAINT chk_verification_reports_total_earning CHECK (((total_earning_member IS NULL) OR (total_family_members IS NULL) OR ((total_earning_member >= 0) AND (total_earning_member <= total_family_members)))),
    CONSTRAINT chk_verification_reports_total_family CHECK (((total_family_members IS NULL) OR ((total_family_members >= 0) AND (total_family_members <= 50)))),
    CONSTRAINT chk_verification_reports_total_images CHECK ((total_images >= 0)),
    CONSTRAINT chk_verification_reports_total_selfies CHECK ((total_selfies >= 0))
);


