--
-- F9.1 (2026-05-26): KYC workflow parity — start/revoke/revisit
-- Mirrors verification_tasks state machine for kyc_document_verifications.
-- - 7 new columns on kyc_document_verifications (start/revoke/revisit state)
-- - new kyc_revocations table (mirrors task_revocations FK shape)
-- - 3 new permissions: kyc.start, kyc.revoke, kyc.revisit
-- All statements idempotent (safe to re-run).
--

ALTER TABLE public.kyc_document_verifications
  ADD COLUMN IF NOT EXISTS started_at timestamp with time zone,
  ADD COLUMN IF NOT EXISTS started_by uuid REFERENCES public.users(id),
  ADD COLUMN IF NOT EXISTS revoked_at timestamp with time zone,
  ADD COLUMN IF NOT EXISTS revoked_by uuid REFERENCES public.users(id),
  ADD COLUMN IF NOT EXISTS revocation_reason text,
  ADD COLUMN IF NOT EXISTS revoke_reason_id integer REFERENCES public.revoke_reasons(id),
  ADD COLUMN IF NOT EXISTS recheck_count integer NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS public.kyc_revocations (
  id bigserial PRIMARY KEY,
  kyc_id uuid NOT NULL REFERENCES public.kyc_document_verifications(id) ON DELETE CASCADE,
  revoked_by_user_id uuid NOT NULL REFERENCES public.users(id),
  revoked_by_role varchar(16) NOT NULL,
  revoked_from_user_id uuid REFERENCES public.users(id),
  revoke_reason text NOT NULL,
  revoke_reason_id integer REFERENCES public.revoke_reasons(id),
  previous_status varchar(64) NOT NULL,
  revoked_at timestamp with time zone NOT NULL DEFAULT now(),
  reassigned boolean NOT NULL DEFAULT false,
  reassigned_to_user_id uuid REFERENCES public.users(id),
  reassigned_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_kyc_revocations_kyc_id ON public.kyc_revocations(kyc_id);
CREATE INDEX IF NOT EXISTS idx_kyc_revocations_revoked_at ON public.kyc_revocations(revoked_at);

ON CONFLICT (code) DO NOTHING;

SELECT r.id, p.id, true
FROM public.roles_v2 r CROSS JOIN public.permissions p
WHERE p.code = 'kyc.start' AND r.name IN ('SUPER_ADMIN','MANAGER','KYC_VERIFIER')
ON CONFLICT DO NOTHING;

SELECT r.id, p.id, true
FROM public.roles_v2 r CROSS JOIN public.permissions p
WHERE p.code IN ('kyc.revoke','kyc.recheck') AND r.name IN ('SUPER_ADMIN','MANAGER')
ON CONFLICT DO NOTHING;

-- F9.1 (2026-05-26): allow COMPLETED → ASSIGNED transition on verification_tasks
-- so KYC recheck can re-open an already-completed parent task. The enforce
-- trigger reads this table; without this row, COMPLETED → * is blocked.
VALUES ('COMPLETED','ASSIGNED')
ON CONFLICT DO NOTHING;

-- F9.2 (2026-05-26): KYC tasks get a "KYC Verification" parent verification_type
-- so shared list views (case-detail Verification Tasks tab, /cases) show a
-- value in the "Verification Type" column instead of "-". The old asymmetric
-- CHECK (which FORCED verification_type_id NULL for KYC) is replaced by a
-- symmetric NOT NULL CHECK. BE field-task dropdowns pass excludeKyc=true to
-- the /verification-types list endpoint so the KYC row stays out of
-- field-task creation flows.
ALTER TABLE public.verification_tasks DROP CONSTRAINT IF EXISTS chk_vt_type_matches_task_type;

VALUES ('KYC Verification', 'KYC', 'KYC document verification (parent type for all kyc_document_verifications)', true)
ON CONFLICT (code) DO NOTHING;

UPDATE public.verification_tasks vt
SET verification_type_id = (SELECT id FROM public.verification_types WHERE code='KYC')
WHERE vt.task_type='KYC' AND vt.verification_type_id IS NULL;

ALTER TABLE public.verification_tasks
  ADD CONSTRAINT chk_vt_type_matches_task_type CHECK (verification_type_id IS NOT NULL);


